import{_ as a,o as p,c as r,a2 as i}from"./chunks/framework.EUByU7Iq.js";const g=JSON.parse('{"title":"《佛经 · 观无量寿佛经》","description":"","frontmatter":{"title":"《佛经 · 观无量寿佛经》","date":"2026-11-24T00:00:00.000Z","categories":["美文","佛经"],"collection":"《佛经 · 观无量寿佛经》","tags":["佛经","刘宋"],"poem":true,"poem_quote":false,"merged":true,"pieces":1,"author":"畺良耶舍 译","source_book":"佛经"},"headers":[],"relativePath":"blogs/佛经·观无量寿佛经/index.md","filePath":"blogs/佛经·观无量寿佛经/index.md"}'),l={name:"blogs/佛经·观无量寿佛经/index.md"};function c(u,s,d,t,e,o){return p(),r("div",null,[...s[0]||(s[0]=[i('<h1 id="《佛经-·-观无量寿佛经》" tabindex="-1">《佛经 · 观无量寿佛经》 <a class="header-anchor" href="#《佛经-·-观无量寿佛经》" aria-label="Permalink to &quot;《佛经 · 观无量寿佛经》&quot;">​</a></h1><p class="poem-meta">刘宋 · 畺良耶舍 译</p><p>全文 21 段，经文与白话逐段对照，收录完整。</p><div class="merged-book"><h3 id="佛说观无量寿佛经" tabindex="-1">佛说观无量寿佛经 <a class="header-anchor" href="#佛说观无量寿佛经" aria-label="Permalink to &quot;佛说观无量寿佛经&quot;">​</a></h3><div class="sutra"><div class="su-pair"><p class="su-org">如是我闻。一时佛在王舍城耆阇崛山中。与大比丘众千二百五十人俱。菩萨三万二千。文殊师利法王子。而为上首。尔时王舍大城有一太子。名阿阇世。随顺调达恶友之教。收执父王频婆娑罗。幽闭置于七重室内。制诸群臣一不得往。国大夫人名韦提希。恭敬大王。澡浴清净。以酥蜜和麨用涂其身。诸璎珞中盛葡萄浆密以上王。尔时大王。食麨饮浆。求水漱口。漱口毕已。合掌恭敬。向耆阇崛山遥礼世尊。而作是言。大目干连是吾亲友。愿兴慈悲授我八戒。时目干连如鹰隼飞疾至王所。日日如是授王八戒。世尊亦遣尊者富楼那。为王说法。如是时间经三七日。王食麨蜜得闻法故。颜色和悦。时阿阇世问守门人。父王今者犹存在耶。时守门者白言。大王。国大夫人身涂麨蜜。璎珞盛浆持用上王。沙门目连及富楼那。从空而来为王说法。不可禁制。时阿阇世闻此语已。怒其母曰。我母是贼。与贼为伴。沙门恶人。幻惑呪术。令此恶王多日不死。即执利剑欲害其母。时有一臣名曰月光。聪明多智。及与耆婆。为王作礼。白言大王。臣闻毘陀论经说。劫初已来。有诸恶王贪国位故。杀害其父一万八千。未曾闻有无道害母。王今为此杀逆之事。污刹利种。臣不忍闻。是栴陀罗。我等不宜复住于此。时二大臣说此语竟。以手按剑却行而退。时阿阇世惊怖惶惧。告耆婆言。汝不为我耶。耆婆白言。大王。慎莫害母。王闻此语忏悔求救。即便舍剑止不害母。勅语内官。闭置深宫不令复出。</p><p class="su-tra">这部经是我亲耳听佛说的。那时佛在王舍城耆阇崛山中，和一千二百五十位大比丘在一起，又有菩萨三万二千，以文殊师利法王子为上首。当时王舍大城有一位太子，名叫阿阇世，听顺了调达这位恶友的教唆，把父王频婆娑罗抓起来，幽禁在七重宫室里面，又约束群臣，一个也不许前去探视。国大夫人韦提希恭敬大王，沐浴清净之后，用酥油、蜂蜜和炒面调和好涂在身上，又在种种璎珞里盛了葡萄浆，秘密送去给大王。那时大王吃了炒面、喝了浆水，要水漱口。漱完口，合掌恭敬，向着耆阇崛山远远礼拜世尊，说道：大目犍连是我的亲友，愿他兴起慈悲，来给我授八戒。那时目犍连像鹰隼飞扑一样赶到大王面前，天天如此给大王授八戒；世尊也派尊者富楼那去为大王说法。这样过了二十一天，大王靠着酥蜜充饥、又时时闻法，颜色温和喜悦。阿阇世问守门人：父王现在可还活着？守门人禀告说：大王，国大夫人身上涂着酥蜜，璎珞里盛着浆水拿来供给大王；沙门目连和富楼那从空中来为大王说法，根本禁不住。阿阇世听了这话，怒骂其母：我母亲就是贼，与贼做伴；这些沙门是恶人，用幻术咒语迷惑人，叫这恶王多日死不了！当即提起利剑要杀母亲。当时有一位大臣名叫月光，聪明多智，与耆婆一同向王行礼，禀告说：臣听说《毗陀论经》讲，劫初以来，诸恶王因贪恋王位而杀害父亲的有一万八千，却从未听说有无道到杀害母亲的。王如今做这等杀逆之事，玷污了刹利种姓，臣不忍听闻——这是旃陀罗的作为，我们不应当再留在这里。两位大臣说完，手按着剑，退身而出。阿阇世惊怖惶恐，对耆婆说：你也不帮我一回吗？耆婆说：大王，千万不要害母亲。王听了这话，忏悔求救，当即丢剑，止住害母之举，只吩咐宫人把夫人关在深宫，不让她再出来。</p></div><div class="su-pair"><p class="su-org">时韦提希被幽闭已。愁忧憔悴。遥向耆阇崛山。为佛作礼而作是言。如来世尊在昔之时。恒遣阿难来慰问我。我今愁忧。世尊威重无由得见。愿遣目连尊者阿难。与我相见。作是语已。悲泣雨泪遥向佛礼。未举头顷。尔时世尊在耆阇崛山。知韦提希心之所念。即勅大目揵连及以阿难。从空而来。佛从耆阇崛山没。于王宫出。时韦提希礼已举头。见世尊释迦牟尼佛。身紫金色坐百宝莲华。目连侍左。阿难在右。释梵护世诸天在虚空中。普雨天华持用供养。时韦提希见佛世尊。自绝璎珞举身投地。号泣向佛白言。世尊。我宿何罪生此恶子。世尊复有何等因缘。与提婆达多共为眷属。唯愿世尊。为我广说无忧恼处。我当往生。不乐阎浮提浊恶世也。此浊恶处。地狱饿鬼畜生盈满。多不善聚。愿我未来不闻恶声。不见恶人。今向世尊五体投地。求哀忏悔。唯愿佛日教我观于清净业处。尔时世尊放眉间光。其光金色。遍照十方无量世界。还住佛顶。化为金台如须弥山。十方诸佛净妙国土。皆于中现。或有国土七宝合成。复有国土纯是莲花。复有国土如自在天宫。复有国土如颇梨镜。十方国土皆于中现。有如是等无量诸佛国土严显可观。令韦提希见。时韦提希白佛言。世尊。是诸佛土。虽复清净皆有光明。我今乐生极乐世界阿弥陀佛所。唯愿世尊。教我思惟教我正受。尔时世尊即便微笑。有五色光从佛口出。一一光照频婆娑罗王顶。尔时大王虽在幽闭。心眼无障遥见世尊。头面作礼。自然增进成阿那含。尔时世尊告韦提希。汝今知不。阿弥陀佛去此不远。汝当系念谛观彼国净业成者。我今为汝广说众譬。亦令未来世一切凡夫欲修净业者得生西方极乐国土。欲生彼国者。当修三福。一者孝养父母。奉事师长。慈心不杀。修十善业。二者受持三归。具足众戒。不犯威仪。三者发菩提心。深信因果。读诵大乘。劝进行者。如此三事名为净业。</p><p class="su-tra">韦提希被幽闭以后，忧愁憔悴，遥向耆阇崛山为佛礼拜，说道：如来世尊从前常常派阿难来慰问我；我如今愁苦，世尊威严深重，无从得见。愿遣目连、尊者阿难与我相见。说了这话，悲泣流泪，遥方向佛礼拜。头还没抬起来，那时世尊在耆阇崛山，已知韦提希心中所念，当即敕令大目犍连和阿难从空而去；佛又从耆阇崛山隐没，出现在王宫。韦提希礼毕抬头，见世尊释迦牟尼佛身紫金色，坐在百宝莲花上，目犍连侍立在左，阿难在右，帝释、梵天、护世诸天在虚空中普遍散下天花用来供养。韦提希见了佛世尊，自己扯落璎珞，扑身投地，号哭着对佛说：世尊，我宿世造了什么罪，生出这等恶子？世尊又有什么因缘，竟与提婆达多同为眷属？唯愿世尊为我广说没有忧恼之处，我愿往生，不再贪恋这阎浮提的浊恶世间——这浊恶之处，地狱、饿鬼、畜生填满，多是不善的聚集；愿我未来不闻恶声、不见恶人。如今我向世尊五体投地，求哀忏悔，唯愿佛日照耀，教我观于清净的业处。那时世尊从眉间放出光来，其光金色，遍照十方无量世界，又回住佛顶，化成如须弥山一般的金台；十方诸佛的净妙国土都在其中显现：有的国土七宝合成，有的国土纯是莲花，有的国土如自在天宫，有的国土像颇梨明镜——十方国土都在其中显现。如此等无量的诸佛国土，庄严显了、可以观见，让韦提希看见。韦提希对佛说：世尊，这些佛土虽然都清净、都有光明，我如今愿生极乐世界阿弥陀佛所在之处；唯愿世尊教我思惟、教我正受。那时世尊随即微笑，有五色光从佛口出，一一光照频婆娑罗王的头顶。那时大王虽在幽闭之中，心眼无障，遥见世尊，头面作礼，自然增进，证得阿那含。世尊告诉韦提希：你知道了吗？阿弥陀佛离这里不远，你应当系念，谛观那国中净业所成之相。我现在为你广说种种譬喻，也让未来世一切想修净业的凡夫，得生西方极乐国土。想生那国的人，应当修三种福：一是孝养父母、奉事师长、慈心不杀、修十善业；二是受持三归、具足众戒、不犯威仪；三是发菩提心、深信因果、读诵大乘、劝勉同行者前进。这三件事，就叫净业。</p></div><div class="su-pair"><p class="su-org">佛告韦提希。汝今知不。此三种业乃是过去未来现在。三世诸佛净业正因。</p><p class="su-tra">佛告诉韦提希：你知道了吗？这三种业，乃是过去、未来、现在三世诸佛净业的正因。</p></div><div class="su-pair"><p class="su-org">佛告阿难及韦提希。谛听谛听善思念之。如来今者。为未来世一切众生为烦恼贼之所害者。说清净业。善哉韦提希快问此事。阿难。汝当受持广为多众宣说佛语。如来今者。教韦提希及未来世一切众生观于西方极乐世界。以佛力故。当得见彼清净国土。如执明镜自见面像。见彼国土极妙乐事。心欢喜故。应时即得无生法忍。</p><p class="su-tra">佛告诉阿难和韦提希：好好听着，好好听着，善于思念它。如来今天为未来世一切被烦恼贼所害的众生，说这清净业。好啊韦提希，你问的正是这件事。阿难，你应当受持，广为大众宣说佛语。如来今天教韦提希和未来世一切众生观西方极乐世界——靠着佛力的缘故，就能见那清净国土，好比手持明镜、自己看见自己的面像。见那国土极妙的乐事，心里欢喜的缘故，当下就证得无生法忍。</p></div><div class="su-pair"><p class="su-org">佛告韦提希。汝是凡夫心想羸劣。未得天眼。不能远观。诸佛如来有异方便。令汝得见。时韦提希白佛言。世尊。如我今者以佛力故见彼国土。若佛灭后诸众生等。浊恶不善五苦所逼。云何当见阿弥陀佛极乐世界。佛告韦提希。汝及众生。应当专心。系念一处。想于西方。云何作想。凡作想者。一切众生自非生盲。有目之徒皆见日没。当起想念。正坐西向谛观于日。令心坚住。专想不移。见日欲没状如悬鼓。既见日已。闭目开目皆令明了。是为日想。名曰初观。作是观者名为正观。若他观者名为邪观。佛告阿难及韦提希。初观成已。次作水想。想见西方一切皆是大水。见水澄清。亦令明了。无分散意。既见水已当起氷想。见氷映彻作琉璃想。此想成已。见琉璃地内外映彻。下有金刚七宝金幢。擎琉璃地。其幢八方八楞具足。一一方面百宝所成。一一宝珠有千光明。一光明八万四千色。映琉璃地。如亿千日不可具见。琉璃地上。以黄金绳杂厕间错。以七宝界分齐分明。一一宝中有五百色光。其光如花。又似星月。悬处虚空成光明台。楼阁千万百宝合成。于台两边各有百亿花幢无量乐器。以为庄严。八种清风从光明出。鼓此乐器。演说苦空无常无我之音。是为水想。名第二观。此想成时。一一观之极令了了。闭目开目不令散失。唯除食时。恒忆此事。作此观者名为正观。若他观者名为邪观。佛告阿难及韦提希。水想成已。名为粗见极乐国地。若得三昧。见彼国地了了分明。不可具说。是为地想。名第三观。</p><p class="su-tra">佛告诉韦提希：你是凡夫，心想羸弱，没得到天眼，不能远观。诸佛如来有特殊的方便，让你得以看见。韦提希对佛说：世尊，像我今天靠佛力能见那国土；若佛灭度之后，众生浊恶不善、被五苦所逼，要怎样才能看见阿弥陀佛的极乐世界呢？佛告诉韦提希：你和众生，应当专心，系念在一处，想往西方。怎么作想？凡是作想的，一切众生只要不是生下来就瞎的，有眼睛的人都见过太阳落山——就应当起想念，端正坐好、面向西方，谛观那落日，让心坚住，专一不移。见太阳将要沉没，形状如悬着的鼓。既已见日，闭眼开眼都让它明明了了。这就叫日想，名叫第一观。这样观的叫正观，若作别的观就叫邪观。佛又告诉阿难和韦提希：第一观成了，接着作水想。想见西方一切都是一片大水，见水澄清，也令明了，不起分散的意念。见水之后，当起冰想；见冰晶莹映照通透，便作琉璃想。这想成了，见琉璃地内外映彻，地下有金刚七宝金幢擎着琉璃地：那金幢八方、八楞具足，每一方面由百宝合成，每一颗宝珠有一千光明，每一光明现八万四千色，映照琉璃地，如亿千个太阳，不能尽看。琉璃地上以黄金绳交错间画，用七宝划界，分齐分明。一一宝中有五百色光，那光如花朵、又如星月，悬在虚空中成光明台；楼阁千万，众宝合成；台的两边各有百亿花幢、无量乐器，用来庄严。八种清风从光明中生出，吹动这些乐器，演出苦、空、无常、无我的音声。这就叫水想，名叫第二观。这想成的时候，一一把它观得极清楚，闭眼开眼都不让它散失——除了吃饭的时候，恒常忆着这件事。这样观的叫正观，若作别的观就叫邪观。佛又告诉阿难和韦提希：水想成了，叫作粗粗见到极乐国土之地；若得了三昧，见那国土之地便了了分明，不可具说。这就叫地想，名叫第三观。</p></div><div class="su-pair"><p class="su-org">佛告阿难。汝持佛语。为未来世一切大众欲脱苦者。说是观地法。若观是地者。除八十亿劫生死之罪。舍身他世必生净国。心得无疑。作是观者名为正观。若他观者名为邪观。佛告阿难及韦提希。地想成已。次观宝树。观宝树者。一一观之作七重行树想。一一树高八千由旬。其诸宝树七宝花叶无不具足。一一华叶作异宝色。琉璃色中出金色光。颇梨色中出红色光。马脑色中出车磲光。车磲色中出绿真珠光。珊瑚琥珀一切众宝以为映饰。妙真珠网弥覆树上。一一树上有七重网。一一网间有五百亿妙华宫殿。如梵王宫。诸天童子自然在中。一一童子有五百亿释迦毘楞伽摩尼宝以为璎珞。其摩尼光照百由旬。犹如和合百亿日月。不可具名。众宝间错色中上者。此诸宝树行行相当。叶叶相次。于众叶间生诸妙花。花上自然有七宝果。一一树叶。纵广正等二十五由旬。其叶千色有百种画。如天缨珞。有众妙华作阎浮檀金色。如旋火轮。宛转叶间踊生诸果。如帝释瓶。有大光明。化成幢幡无量宝盖。是宝盖中。映现三千大千世界一切佛事。十方佛国亦于中现。见此树已。亦当次第一一观之。观见树茎枝叶华果。皆令分明。是为树想。名第四观。作是观者名为正观。若他观者名为邪观。佛告阿难及韦提希。树想成已。次当想水。欲想水者。极乐国土有八池水。一一池水七宝所成。其宝柔软从如意珠王生。分为十四支。一一支作七宝色。黄金为渠。渠下皆以杂色金刚以为底沙。一一水中有六十亿七宝莲花。一一莲华团圆正等十二由旬。其摩尼水流注华间寻树上下。其声微妙演说苦空无常无我诸波罗蜜。复有赞叹诸佛相好者。从如意珠王踊出金色微妙光明。其光化为百宝色鸟。和鸣哀雅。常赞念佛念法念僧。是为八功德水想。名第五观。作是观者名为正观。若他观者名为邪观。佛告阿难及韦提希。众宝国土。一一界上有五百亿宝楼。其楼阁中有无量诸天。作天伎乐。又有乐器悬处虚空。如天宝幢不鼓自鸣。此众音中。皆说念佛念法念比丘僧。此想成已。名为粗见极乐世界宝树宝地宝池。是为总观想。名第六观。若见此者。除无量亿劫极重恶业。命终之后必生彼国。作是观者名为正观。若他观者名为邪观。佛告阿难及韦提希。谛听谛听善思念之。吾当为汝分别解说除苦恼法。汝等忆持。广为大众分别解说。说是语时。无量寿佛住立空中。观世音大势至。是二大士侍立左右。光明炽盛不可具见。百千阎浮檀金色不得为比。</p><p class="su-tra">佛告诉阿难：你受持佛语，为未来世一切想要离苦的大众，说这观地之法。若观这地的，能除八十亿劫生死之罪，舍身之后必生净国，心中决定无疑。这样观的叫正观，若作别的观就叫邪观。佛又告诉阿难和韦提希：地想成了，接着观宝树。观宝树，应当一树一树地观，作七重行树想。每一树高八千由旬，那些宝树七宝的花叶无不具足：一一华叶现出不同的宝色——琉璃色中出金色光，颇梨色中出红色光，马脑色中出车渠光，车渠色中出绿真珠光，珊瑚、琥珀一切众宝都用来映衬庄严；妙真珠网弥覆在树上。每一树上有七重网，每一网间有五百亿妙华宫殿，如同梵王宫；诸天童子自然在其中，每一童子有五百亿释迦毗楞伽摩尼宝做璎珞，那摩尼光照百由旬，犹如把百亿日月合在一起，不可具说，是众宝交错中颜色最上的。这些宝树行行相当、叶叶相次，在众叶之间生出种种妙花，花上自然有七宝果。每一片叶纵横正等二十五由旬，其叶千色、有百种画纹如天璎珞；有众妙花作阎浮檀金色，如旋转的火轮宛转叶间，踊出诸果如帝释的宝瓶，有大光明，化成幢幡与无量宝盖。那宝盖之中映现三千大千世界一切佛事，十方佛国也在其中显现。见此树已，也应当次第一一观过：树的茎、枝、叶、华、果都令分明。这就叫树想，名叫第四观。这样观的叫正观，若作别的观就叫邪观。佛又告诉阿难和韦提希：树想成了，接着应当想水。要想到极乐国土有八池水，每一池水七宝所成；那宝性柔软，从如意珠王生出，分为十四支，每一支作七宝色；黄金作渠，渠下都以杂色金刚做底沙。一一水中有六十亿七宝莲花，每一莲花团圆正等十二由旬。那摩尼水流注花间、沿着树上下流动，其声微妙，演说苦、空、无常、无我与诸波罗蜜，又有赞叹诸佛相好的。从如意珠王踊出金色微妙光明，其光化成百宝色鸟，和鸣哀雅，常常赞叹念佛、念法、念僧。这就叫八功德水想，名叫第五观。这样观的叫正观，若作别的观就叫邪观。佛又告诉阿难和韦提希：众宝国土，每一界上有五百亿宝楼，楼阁中有无量诸天演奏天乐；又有乐器悬在虚空中，如天上的宝幢，不用敲打自己会响。这一切音声之中，都在说念佛、念法、念比丘僧。这想成了，叫作粗见极乐世界的宝树、宝地、宝池。这就叫总观想，名叫第六观。若见此相的，能除无量亿劫极重恶业，命终之后必生彼国。这样观的叫正观，若作别的观就叫邪观。佛又告诉阿难和韦提希：好好听着，善于思念。我当为你分别解说除苦恼的法，你们要忆持，也广为大众分别解说。说这话时，无量寿佛住立在空中，观世音、大势至两位大士侍立在左右，光明炽盛不可具见，百千阎浮檀金色也比不上。</p></div><div class="su-pair"><p class="su-org">时韦提希见无量寿佛已。接足作礼。白佛言。世尊。我今因佛力故。得见无量寿佛及二菩萨。未来众生。当云何观无量寿佛及二菩萨。佛告韦提希。欲观彼佛者。当起想念。于七宝地上作莲花想。令其莲花一一叶作百宝色。有八万四千脉。犹如天画一一脉有八万四千光。了了分明皆令得见。华叶小者纵广二百五十由旬。如是莲华有八万四千大叶。一一叶间。有百亿摩尼珠王。以为映饰。一一摩尼珠放千光明。其光如盖七宝合成。遍覆地上。释迦毘楞伽摩尼宝以为其台。此莲花台。八万金刚甄叔迦宝。梵摩尼宝妙真珠网。以为交饰。于其台上。自然而有四柱宝幢。一一宝幢如百千万亿须弥山。幢上宝缦如夜摩天宫。复有五百亿微妙宝珠。以为映饰。一一宝珠有八万四千光。一一光作八万四千异种金色。一一金色遍其宝土。处处变化各作异相。或为金刚台。或作真珠网。或作杂花云。于十方面随意变现施作佛事。是为花座想。名第七观。</p><p class="su-tra">韦提希见无量寿佛以后，捧住佛足作礼，对佛说：世尊，我如今靠佛力的缘故，得以见无量寿佛和两位菩萨。未来众生应当怎样观无量寿佛和两位菩萨呢？佛告诉韦提希：要观那佛的，应当起想念，在七宝地上作莲花想：让那莲花一一叶作百宝色，有八万四千脉纹，犹如天上的画纹；一一脉有八万四千光，了了分明，都令得见。花叶小的也有纵横二百五十由旬；这样一朵莲花有八万四千大叶，一一叶间有百亿摩尼珠王用来映衬庄严；一一摩尼珠放千光明，那光如宝盖、七宝合成，遍覆地上。用释迦毗楞伽摩尼宝做成花台；这莲花台以八万金刚、甄叔迦宝、梵摩尼宝、妙真珠网交错庄严。台之上自然有四柱宝幢，一一宝幢如百千万亿须弥山；幢上的宝缦如夜摩天宫；又有五百亿微妙宝珠用来映衬。一一宝珠有八万四千光，一一光作八万四千种不同的金色；一一金色遍及其国土，处处变化、各作异相：或作金刚台，或作真珠网，或作杂花云——在十方随意变现，施作佛事。这就叫花座想，名叫第七观。</p></div><div class="su-pair"><p class="su-org">佛告阿难。如此妙花。是本法藏比丘愿力所成。若欲念彼佛者。当先作此妙花座想。作此想时不得杂观。皆应一一观之。一一叶。一一珠。一一光。一一台。一一幢皆令分明。如于镜中自见面像。此想成者。灭除五百亿劫生死之罪。必定当生极乐世界。作是观者名为正观。若他观者名为邪观。</p><p class="su-tra">佛告诉阿难：这样的妙花，是本法藏比丘的愿力所成。若要念那佛，应当先作这妙花座想。作这想时不得夹杂别观，都应当一一观过：一一叶、一一珠、一一光、一一台、一一幢都令分明，如同在镜中自己看见自己的面像。这想成的，灭除五百亿劫生死之罪，必定当生极乐世界。这样观的叫正观，若作别的观就叫邪观。</p></div><div class="su-pair"><p class="su-org">佛告阿难及韦提希。见此事已。次当想佛。所以者何。诸佛如来是法界身。遍入一切众生心想中。是故汝等心想佛时。是心即是三十二相八十随形好。是心作佛是心是佛。诸佛正遍知海从心想生。是故应当一心系念谛观彼佛多陀阿伽度阿罗呵三藐三佛陀。想彼佛者。先当想像。闭目开目见一宝像如阎浮檀金色坐彼华上。像既坐已。心眼得开。了了分明。见极乐国七宝庄严宝地宝池宝树行列。诸天宝缦弥覆树上。众宝罗网满虚空中。见如此事极令明了如观掌中。见此事已。复当更作一大莲华在佛左边。如前莲华等无有异。复作一大莲华在佛右边。想一观世音菩萨像坐左华座。亦放金光如前无异。想一大势至菩萨像坐右华座。此想成时。佛菩萨像皆放妙光。其光金色照诸宝树。一一树下亦有三莲华。诸莲华上各有一佛二菩萨像。遍满彼国。此想成时。行者当闻水流光明及诸宝树凫鴈鸳鸯皆说妙法。出定入定恒闻妙法。行者所闻。出定之时忆持不舍。令与修多罗合。若不合者名为妄想。若与合者。名为麁想见极乐世界。是为想像。名第八观。作是观者。除无量亿劫生死之罪。于现身中得念佛三昧。作是观者名为正观。若他观者名为邪观。</p><p class="su-tra">佛告诉阿难和韦提希：见到这些事之后，接着应当想佛。为什么？诸佛如来是法界之身，遍入一切众生的心想之中。所以你们心想佛时，这一念心就是三十二相、八十种随形好——是心作佛，是心是佛。诸佛的正遍知海，从心想生。所以应当一心系念，谛观那佛（如来、应供、正遍知）。想那佛，先当想像：闭眼开眼，见一尊宝像如阎浮檀金色，坐在那花上。像既坐已，心眼得开，了了分明，见极乐国七宝庄严——宝地、宝池、宝树行列，诸天宝缦弥覆树上，众宝罗网满虚空中；见如此事，极令明了，如看手掌中的东西。见此事已，又应当更作一大莲花在佛左边，与先前的莲花等同无别；再作一大莲花在佛右边；想一尊观世音菩萨像坐在左边的花座上，也放金光，如前无异；想一大势至菩萨像坐在右边的花座上。这想成的时候，佛与菩萨的像都放妙光，那光是金色，照诸宝树；每一树下也有三朵莲花，诸莲花上各有一佛二菩萨像，遍满那国。这想成的时候，修行人当听到水流、光明以及诸宝树、凫雁鸳鸯都在说法；出定入定恒常闻法。修行人所听到的，出定之时忆持不忘，并让它与经教相合。若不相合，名为妄想；若与经教相合，名为粗想见极乐世界。这就叫想像，名叫第八观。作是观的，除无量亿劫生死之罪，在现身之中得念佛三昧。这样观的叫正观，若作别的观就叫邪观。</p></div><div class="su-pair"><p class="su-org">佛告阿难及韦提希。此想成已。次当更观无量寿佛身相光明。阿难当知。无量寿佛身。如百千万亿夜摩天阎浮檀金色。佛身高六十万亿那由他恒河沙由旬。眉间白毫右旋宛转如五须弥山。佛眼清净如四大海水清白分明。身诸毛孔演出光明如须弥山。彼佛圆光如百亿三千大千世界。于圆光中。有百万亿那由他恒河沙化佛。一一化佛。亦有众多无数化菩萨。以为侍者。无量寿佛有八万四千相。一一相中。各有八万四千随形好。一一好中复有八万四千光明。一一光明遍照十方世界。念佛众生摄取不舍。其光相好及与化佛。不可具说。但当忆想令心明见。见此事者。即见十方一切诸佛。以见诸佛故名念佛三昧。作是观者。名观一切佛身。以观佛身故亦见佛心。诸佛心者大慈悲是。以无缘慈摄诸众生。作此观者。舍身他世生诸佛前。得无生忍。是故智者应当系心谛观无量寿佛。观无量寿佛者。从一相好入。但观眉间白毫极令明了。见眉间白毫相者。八万四千相好自然当见。见无量寿佛者。即见十方无量诸佛。得见无量诸佛故。诸佛现前受记。是为遍观一切色想。名第九观。作是观者名为正观。若他观者名为邪观。</p><p class="su-tra">佛告诉阿难和韦提希：这想成了，接着应当再观无量寿佛的身相光明。阿难当知：无量寿佛的身，如百千万亿夜摩天的阎浮檀金色；佛身高六十万亿那由他恒河沙由旬。眉间白毫右旋宛转，如五座须弥山；佛眼清净如四大海水，清白分明；身上诸毛孔演出光明如须弥山。那佛的圆光如百亿三千大千世界；圆光之中有百万亿那由他恒河沙的化佛，每一尊化佛也有众多无数的化菩萨做侍者。无量寿佛有八万四千相，每一相中各有八万四千随形好，每一好中复有八万四千光明，一一光明遍照十方世界，念佛的众生摄取不舍。那光明、相好以及化佛，不可具说，只应当忆想，让心明见。见此事的，就是见十方一切诸佛；因见诸佛的缘故，名叫念佛三昧。作是观的，名叫观一切佛身；因为观佛身，也就见佛心——诸佛的心，就是大慈悲，用无缘之慈摄受众生。作这观的人，舍身之后一世生在诸佛面前，得无生法忍。所以智者应当系心谛观无量寿佛。观无量寿佛，从一相好入手：只观眉间白毫，极令明了。见眉间白毫相的，八万四千相好自然就会看见；见无量寿佛的，就是见十方无量诸佛。因见无量诸佛的缘故，诸佛现前授记。这就叫遍观一切色想，名叫第九观。这样观的叫正观，若作别的观就叫邪观。</p></div><div class="su-pair"><p class="su-org">佛告阿难及韦提希。见无量寿佛了了分明已。次亦应观观世音菩萨。此菩萨身长八十亿那由他恒河沙由旬。身紫金色。顶有肉髻。项有圆光。面各百千由旬。其圆光中有五百化佛。如释迦牟尼。一一化佛。有五百菩萨无量诸天。以为侍者。举身光中五道众生。一切色相皆于中现。顶上毘楞伽摩尼妙宝。以为天冠。其天冠中有一立化佛。高二十五由旬。观世音菩萨面如阎浮檀金色。眉间毫相备七宝色。流出八万四千种光明。一一光明。有无量无数百千化佛。一一化佛。无数化菩萨以为侍者。变现自在满十方界。臂如红莲花色。有八十亿微妙光明。以为璎珞。其璎珞中。普现一切诸庄严事。手掌作五百亿杂莲华色。手十指端。一一指端有八万四千画。犹如印文。一一画有八万四千色。一一色有八万四千光。其光柔软普照一切。以此宝手接引众生。举足时。足下有千辐轮相。自然化成五百亿光明台。下足时。有金刚摩尼花。布散一切莫不弥满。其余身相众好具足。如佛无异。唯顶上肉髻及无见顶相。不及世尊。是为观观世音菩萨真实色身想。名第十观。</p><p class="su-tra">佛告诉阿难和韦提希：见无量寿佛了了分明之后，接着也应当观观世音菩萨。这菩萨身长八十亿那由他恒河沙由旬，身紫金色，顶有肉髻，项有圆光，面各百千由旬。那圆光中有五百化佛如释迦牟尼，每一化佛有五百菩萨、无量诸天做侍者。全身光中，五道众生的一切色相都在其中显现。顶上以毗楞伽摩尼妙宝做成天冠，天冠中有一尊立着的化佛，高二十五由旬。观世音菩萨面如阎浮檀金色，眉间毫相具备七宝之色，流出八万四千种光明；一一光明中有无量无数百千化佛，每一化佛有无数化菩萨做侍者，变现自在，满十方界。臂如红莲花色，有八十亿微妙光明做璎珞，那璎珞之中普现一切庄严之事。手掌作五百亿杂莲花色；十只指端，一一指端有八万四千纹画如印文，一一画有八万四千色，一一色有八万四千光，其光柔软，普照一切——就以此宝手接引众生。举足的时候，足下有千辐轮相，自然化成五百亿光明台；下足的时候，有金刚摩尼花布散一切，无不充满。其余身相众好具足，与佛没有差别，只有顶上的肉髻和无见顶相比不上世尊。这就叫观观世音菩萨真实色身想，名叫第十观。</p></div><div class="su-pair"><p class="su-org">佛告阿难。若欲观观世音菩萨当作是观。作是观者不遇诸祸。净除业障。除无数劫生死之罪。如此菩萨。但闻其名获无量福。何况谛观。若有欲观观世音菩萨者。当先观顶上肉髻。次观天冠。其余众相亦次第观之。悉令明了如观掌中。作是观者名为正观。若他观者名为邪观。</p><p class="su-tra">佛告诉阿难：若要观观世音菩萨，就当这样观。这样观的人不遇各种灾祸，净除业障，除无数劫生死之罪。这样的菩萨，只听他的名号就得无量福，何况谛观。若有想观观世音菩萨的，应当先观顶上肉髻，其次观天冠，其余众相也次第观之，都令明了如看手掌之中。这样观的叫正观，若作别的观就叫邪观。</p></div><div class="su-pair"><p class="su-org">佛告阿难及韦提希。次观大势至菩萨。此菩萨身量大小亦如观世音。圆光面各二百二十五由旬。照二百五十由旬。举身光明照十方国。作紫金色。有缘众生皆悉得见。但见此菩萨一毛孔光。即见十方无量诸佛净妙光明。是故号此菩萨名无边光。以智慧光普照一切。令离三涂得无上力。是故号此菩萨名大势至。此菩萨天冠有五百宝莲华。一一宝华有五百宝台。一一台中。十方诸佛净妙国土广长之相。皆于中现。顶上肉髻如钵头摩花。于肉髻上有一宝瓶。盛诸光明普现佛事。余诸身相如观世音等无有异。此菩萨行时。十方世界一切震动。当地动处各有五百亿宝花。一一宝花庄严高显。如极乐世界。此菩萨坐时。七宝国土一时动摇。从下方金光佛刹。乃至上方光明王佛刹。于其中间无量尘数分身无量寿佛分身观世音大势至。皆悉云集极乐国土。侧塞空中坐莲华座。演说妙法度苦众生。作此观者。名为观见大势至菩萨。是为观大势至色身相。观此菩萨者名第十一观。除无数劫阿僧祇生死之罪。作是观者不处胞胎。常游诸佛净妙国土。此观成已。名为具足观观世音及大势至。作是观者名为正观。若他观者名为邪观。佛告阿难及韦提希。见此事时当起想作心自见生于西方极乐世界。于莲华中结跏趺坐。作莲华合想。作莲华开想。莲华开时。有五百色光来照身想。眼目开想。见佛菩萨满虚空中。水鸟树林及与诸佛。所出音声皆演妙法。与十二部经合。若出定时忆持不失。见此事已。名见无量寿佛极乐世界。是为普观想。名第十二观。无量寿佛化身无数。与观世音及大势至。常来至此行人之所。作是观者名为正观。若他观者名为邪观。</p><p class="su-tra">佛告诉阿难和韦提希：接着观大势至菩萨。这菩萨身量大小也同观世音；圆光面各二百二十五由旬，照二百五十由旬，举身光明照十方国，作紫金色，有缘的众生都能得见。只要看见这菩萨一个毛孔的光，就能见十方无量诸佛的净妙光明，因此这菩萨的名号叫无边光；以智慧光普照一切，令众生离开三涂、得无上力，因此叫大势至。这菩萨的天冠有五百宝莲花，一一宝华有五百宝台，一一台中，十方诸佛净妙国土的广长之相都在其中显现。顶上肉髻如钵头摩花，肉髻之上有一宝瓶，盛诸光明，普现佛事。其余身相与观世音等同无别。这菩萨行走时，十方世界一切震动；在地动之处各有五百亿宝花，一一宝花庄严高显如极乐世界。这菩萨坐下时，七宝国土一时动摇。从下方金光佛刹乃至上方光明王佛刹，这中间无量尘数的分身无量寿佛、分身观世音、分身大势至，都云集到极乐国土，充满空中，坐莲花座，演说妙法，度苦难众生。这样观的，名叫观见大势至菩萨，也就是观大势至的色身相；观这菩萨名叫第十一观，能除无数劫阿僧祇生死之罪。作这观的人不投生胞胎，常游诸佛的净妙国土。这观成了，叫作具足观观世音及大势至。这样观的叫正观，若作别的观就叫邪观。佛又告诉阿难和韦提希：见这些事时，应当起想、作心，自己见生于西方极乐世界，在莲花中结跏趺坐：先作莲花合拢之想，再作莲花开放之想。莲花开时，有五百色光来照自身之想、眼目睁开之想，见佛、菩萨满虚空中，水鸟树林以及诸佛所出的音声都在演妙法，与十二部经相合；出定的时候忆持不失。见到这些事之后，名叫见无量寿佛极乐世界。这就叫普观想，名叫第十二观。无量寿佛的化身无数，与观世音、大势至常来到这里修行之人的住处。这样观的叫正观，若作别的观就叫邪观。</p></div><div class="su-pair"><p class="su-org">佛告阿难及韦提希。若欲至心生西方者。先当观于一丈六像在池水上。如先所说。无量寿佛身量无边。非是凡夫心力所及。然彼如来宿愿力故。有忆想者必得成就。但想佛像得无量福。况复观佛具足身相。阿弥陀佛神通如意。于十方国变现自在。或现大身满虚空中。或现小身丈六八尺。所现之形皆真金色。圆光化佛及宝莲花。如上所说。观世音菩萨及大势至。于一切处身同。众生但观首相。知是观世音。知是大势至。此二菩萨助阿弥陀佛。普化一切。是为杂想观。名第十三观。作是观者名为正观。若他观者名为邪观。</p><p class="su-tra">佛告诉阿难和韦提希：若要至心求生西方的，应当先观一尊丈六的像在池水之上。如先前所说，无量寿佛身量无边，不是凡夫的心力所能到；但靠那位如来宿世愿力的缘故，有忆想的人必定能够成就。只想像佛像就得无量福，何况具足观佛的身相。阿弥陀佛神通如意，在十方国变现自在：或现大身满虚空中，或现小身丈六、八尺。所示现的形相都是真金色，圆光、化佛和宝莲花如上面所说。观世音菩萨和大势至在一切处身相也相同，众生只观其头首之相，就知道这是观世音、这是大势至。这两位菩萨帮助阿弥陀佛，普遍化导一切。这就叫杂想观，名叫第十三观。这样观的叫正观，若作别的观就叫邪观。</p></div><div class="su-pair"><p class="su-org">佛告阿难。及韦提希。凡生西方有九品人。上品上生者。若有众生愿生彼国者。发三种心即便往生。何等为三。一者至诚心。二者深心。三者回向发愿心。具三心者必生彼国。复有三种众生。当得往生。何等为三。一者慈心不杀具诸戒行。二者读诵大乘方等经典。三者修行六念回向发愿生彼佛国。具此功德。一日乃至七日。即得往生。生彼国时。此人精进勇猛故。阿弥陀如来与观世音及大势至无数化佛百千比丘声闻大众无量诸天。七宝宫殿。观世音菩萨执金刚台。与大势至菩萨至行者前。阿弥陀佛放大光明照行者身。与诸菩萨授手迎接。观世音大势至与无数菩萨。赞叹行者劝进其心。行者见已欢喜踊跃。自见其身乘金刚台。随从佛后。如弹指顷往生彼国。生彼国已。见佛色身众相具足。见诸菩萨色相具足。光明宝林演说妙法。闻已即悟无生法忍。经须臾间历事诸佛。遍十方界。于诸佛前次第受记。还至本国。得无量百千陀罗尼门。是名上品上生者。上品中生者。不必受持读诵方等经典。善解义趣。于第一义心不惊动。深信因果不谤大乘。以此功德。回向愿求生极乐国。行此行者命欲终时。阿弥陀佛与观世音及大势至。无量大众眷属围绕。持紫金台至行者前赞言。法子。汝行大乘解第一义。是故我今来迎接汝。与千化佛一时授手。行者自见坐紫金台。合掌叉手赞叹诸佛。如一念顷。即生彼国七宝池中。此紫金台如大宝花。经宿即开。行者身作紫磨金色。足下亦有七宝莲华。佛及菩萨俱放光明。照行者身目即开明。因前宿习普闻众声。纯说甚深第一义谛。即下金台礼佛合掌赞叹世尊。经于七日。应时即于阿耨多罗三藐三菩提。得不退转。应时即能飞至十方。历事诸佛。于诸佛所修诸三昧。经一小劫得无生法忍现前受记。是名上品中生者。上品下生者。亦信因果不谤大乘。但发无上道心。以此功德。回向愿求生极乐国。彼行者命欲终时。阿弥陀佛及观世音并大势至。与诸眷属持金莲华。化作五百化佛来迎此人。五百化佛一时授手。赞言。法子。汝今清净发无上道心。我来迎汝。见此事时。即自见身坐金莲花。坐已华合。随世尊后即得往生七宝池中。一日一夜莲花乃开。七日之中乃得见佛。虽见佛身于众相好心不明了。于三七日后乃了了见。闻众音声皆演妙法。游历十方供养诸佛。于诸佛前闻甚深法。经三小劫得百法明门。住欢喜地。是名上品下生者。是名上辈生想。名第十四观。作是观者名为正观。若他观者名为邪观。</p><p class="su-tra">佛告诉阿难和韦提希：凡生西方的人有九品。上品上生的：若有众生愿生彼国，发三种心便能往生。哪三种？一是至诚心，二是深心，三是回向发愿心。具三心的一定生彼国。又有三种众生当得往生：一是慈心不杀、具诸戒行；二是读诵大乘方等经典；三是修行六念，回向发愿生彼佛国。具此功德，一日乃至七日之间即得往生。生彼国时，这人精进勇猛的缘故，阿弥陀如来与观世音、大势至，无数化佛、百千比丘声闻大众、无量诸天，七宝宫殿，观世音菩萨手执金刚台，与大势至菩萨一同到修行人面前；阿弥陀佛放大光明照在修行人身上，与诸菩萨一同授手迎接。观世音、大势至与无数菩萨赞叹修行人、劝进其心。修行人见了，欢喜踊跃，自己见其身乘金刚台，随从在佛后，如弹指顷往生彼国。生彼国已，见佛色身众相具足，见诸菩萨色相具足，光明宝林演说妙法，听了即刻悟无生法忍。经过一会儿，历事诸佛，遍十方界，在诸佛前次第受记，回到本国，得无量百千陀罗尼门。这就叫上品上生。上品中生的：不必受持读诵方等经典，但能善解义趣，对于第一义心不惊动，深信因果，不谤大乘；以此功德回向愿生极乐国。这样修行的人命欲终时，阿弥陀佛与观世音、大势至及无量大众眷属围绕，持紫金台到修行人前，赞言：法子，你行大乘、解第一义，所以我今天来迎接你。与千尊化佛同时授手。修行人自见坐紫金台，合掌叉手赞叹诸佛；如一念顷，即生彼国七宝池中。这紫金台如大宝花，过一夜便开；修行人身作紫磨金色，足下也有七宝莲花。佛与菩萨都放光明照在修行人身上，眼睛即刻开明，因从前的宿习，普闻众声都纯然说着甚深第一义谛。随即下金台礼佛、合掌赞叹世尊。经过七日，当下便在无上正等正觉得不退转；当下即能飞至十方，历事诸佛，在诸佛所修诸三昧；经过一小劫得无生法忍，现前受记。这就叫上品中生。上品下生的：也信因果、不谤大乘，只是发无上道心，以此功德回向愿生极乐国。那修行人命欲终时，阿弥陀佛及观世音、大势至与诸眷属持金莲花，化作五百化佛来迎此人；五百化佛同时授手，赞言：法子，你现在清净、发了无上道心，我来迎你。见到此事时，即刻自见身坐金莲花；坐定花即合拢，随从世尊之后便生七宝池中。一日一夜莲花才开；七日之中得以见佛，虽见佛身，对于众相好心里还看不分明；到三七日之后才看得了了。闻众音声都在演妙法，游历十方供养诸佛，在诸佛前闻甚深法；经过三小劫得百法明门，住欢喜地。这就叫上品下生。这叫做上辈生想，名叫第十四观。这样观的叫正观，若作别的观就叫邪观。</p></div><div class="su-pair"><p class="su-org">佛告阿难及韦提希。中品上生者。若有众生受持五戒。持八戒斋。修行诸戒。不造五逆。无众过恶。以此善根。回向愿求生于西方极乐世界。行者临命终时。阿弥陀佛与诸比丘眷属围绕。放金色光至其人所。演说苦空无常无我。赞叹出家得离众苦。行者见已心大欢喜。自见己身坐莲花台。长跪合掌为佛作礼。未举头顷即得往生极乐世界。莲花寻开。当华敷时。闻众音声赞叹四谛。应时即得阿罗汉道。三明六通具八解脱。是名中品上生者。中品中生者。若有众生。若一日一夜持八戒斋。若一日一夜持沙弥戒。若一日一夜持具足戒。威仪无缺。以此功德。回向愿求生极乐国。戒香薰修。如此行者命欲终时。见阿弥陀佛与诸眷属放金色光。持七宝莲花至行者前。行者自闻空中有声。赞言。善男子。如汝善人。随顺三世诸佛教故。我来迎汝。行者自见坐莲花上。莲花即合。生于西方极乐世界。在宝池中。经于七日莲花乃敷。花既敷已。开目合掌赞叹世尊。闻法欢喜得须陀洹。经半劫已成阿罗汉。是名中品中生者。中品下生者。若有善男子善女人。孝养父母行世仁义。此人命欲终时遇善知识。为其广说阿弥陀佛国土乐事。亦说法藏比丘四十八大愿。闻此事已寻即命终。譬如壮士屈伸臂顷。即生西方极乐世界。生经七日遇观世音及大势至。闻法欢喜得须陀洹。过一小劫成阿罗汉。是名中品下生者。是名中辈生想。名第十五观。作是观者名为正观。若他观者名为邪观。</p><p class="su-tra">佛告诉阿难和韦提希：中品上生的：若有众生受持五戒、持八戒斋，修行诸戒，不造五逆，没有种种过恶，以此善根回向愿生西方极乐世界。修行人临命终时，阿弥陀佛与诸比丘眷属围绕，放金色光到其人所，演说苦、空、无常、无我，赞叹出家得离众苦。修行人见了，心大欢喜，自见己身坐莲花台，长跪合掌为佛作礼；头还没抬起，即得往生极乐世界，莲花随即开放。当花开时，闻众音声赞叹四谛，当下即得阿罗汉道，三明六通、具八解脱。这就叫中品上生。中品中生的：若有众生，或一日一夜持八戒斋，或一日一夜持沙弥戒，或一日一夜持具足戒，威仪无缺，以此功德回向愿生极乐国，以戒香薰修——这样修行的人命欲终时，见阿弥陀佛与诸眷属放金色光，持七宝莲花到修行人前；修行人自闻空中有声，赞言：善男子，像你这样的善人，随顺三世诸佛的教诫，所以我来迎你。修行人自见坐在莲花之上，莲花随即合拢，生到西方极乐世界的宝池中。经过七日莲花才开；花开之后，开目合掌赞叹世尊，闻法欢喜得须陀洹；经过半劫已证阿罗汉。这就叫中品中生。中品下生的：若有善男子、善女人孝养父母、行世间的仁义，这人命欲终时遇到善知识，为他广说阿弥陀佛国土的乐事，也说法藏比丘的四十八大愿；听了这些事，随即命终，譬如壮士屈伸臂顷，即生西方极乐世界。生后经七日遇观世音及大势至，闻法欢喜得须陀洹；过一小劫证阿罗汉。这就叫中品下生。这叫做中辈生想，名叫第十五观。这样观的叫正观，若作别的观就叫邪观。</p></div><div class="su-pair"><p class="su-org">佛告阿难及韦提希。下品上生者。或有众生作众恶业。虽不诽谤方等经典。如此愚人。多造恶法无有惭愧。命欲终时遇善知识。为赞大乘十二部经首题名字。以闻如是诸经名故。除却千劫极重恶业。智者复教合掌叉手。称南无阿弥陀佛。称佛名故。除五十亿劫生死之罪。尔时彼佛。即遣化佛化观世音化大势至。至行者前。赞言善哉善男子。汝称佛名故诸罪消灭。我来迎汝。作是语已。行者即见化佛光明遍满其室。见已欢喜即便命终。乘宝莲花。随化佛后生宝池中。经七七日莲花乃敷。当花敷时。大悲观世音菩萨。及大势至菩萨。放大光明住其人前。为说甚深十二部经。闻已信解发无上道心。经十小劫。具百法明门。得入初地。是名下品上生者。得闻佛名法名及闻僧名。闻三宝名即得往生。佛告阿难及韦提希。下品中生者。或有众生。毁犯五戒八戒及具足戒。如此愚人。偷僧祇物盗现前僧物。不净说法无有惭愧。以诸恶法而自庄严。如此罪人。以恶业故应堕地狱。命欲终时。地狱众火一时俱至。遇善知识以大慈悲。即为赞说阿弥陀佛十力威德。广赞彼佛光明神力。亦赞戒定慧解脱解脱知见。此人闻已除八十亿劫生死之罪。地狱猛火化为凉风。吹诸天华。华上皆有化佛菩萨。迎接此人。如一念顷。即得往生七宝池中莲花之内。经于六劫莲花乃敷当华敷时。观世音大势至。以梵音声安慰彼人。为说大乘甚深经典。闻此法已。应时即发无上道心。是名下品中生者。佛告阿难及韦提希。下品下生者。或有众生作不善业五逆十恶。具诸不善。如此愚人以恶业故。应堕恶道经历多劫受苦无穷。如此愚人临命终时。遇善知识种种安慰为说妙法教令念佛。彼人苦逼不遑念佛。善友告言。汝若不能念彼佛者。应称归命无量寿佛。如是至心令声不绝。具足十念称南无阿弥陀佛。称佛名故。于念念中。除八十亿劫生死之罪。命终之时见金莲花犹如日轮住其人前。如一念顷即得往生极乐世界。于莲花中满十二大劫。莲花方开当花敷时。观世音大势至以大悲音声。即为其人广说实相除灭罪法。闻已欢喜。应时即发菩提之心。是名下品下生者。是名下辈生想。名第十六观。</p><p class="su-tra">佛告诉阿难和韦提希：下品上生的：或有众生作种种恶业，虽然不诽谤方等经典，但这愚人多造恶法、毫无惭愧，命欲终时遇到善知识，为他赞叹大乘十二部经的经题名字；因为听到这些经名的缘故，除却千劫极重恶业。智者又教他合掌叉手，称南无阿弥陀佛——称佛名的缘故，除五十亿劫生死之罪。那时那佛即刻遣化佛、化观世音、化大势至到修行人前，赞言：善哉，善男子，你称佛名，诸罪消灭，我来迎你。说了这话，修行人即见化佛的光明遍满其室；见了欢喜，随即命终，乘宝莲花随化佛之后生宝池中。经过四十九日莲花才开。当花开时，大悲观世音菩萨和大势至菩萨放大光明住在那人面前，为他解说甚深十二部经；听了信解，发无上道心。经过十小劫，具足百法明门，得入初地。这就叫下品上生。若能闻佛名、法名以及僧名，闻三宝名即得往生。佛告诉阿难和韦提希：下品中生的：或有众生毁犯五戒、八戒及具足戒，这愚人偷僧祇物、盗现前僧物，不清净地说法、无有惭愧，用种种恶法自我夸饰。这样的罪人，以恶业的缘故应堕地狱；命欲终时，地狱众火一时俱至。遇到善知识以大慈悲，即刻为他赞说阿弥陀佛的十力威德，广赞那佛的光明神力，也赞叹戒、定、慧、解脱、解脱知见。这人听了，除八十亿劫生死之罪，地狱猛火化为凉风，吹来诸天华，华上都有化佛菩萨迎接此人。如一念顷，即得往生七宝池中的莲花之内；经过六劫莲花才开。当花开时，观世音、大势至以梵天般的音声安慰那人，为他解说大乘甚深经典；闻此法已，当下即发无上道心。这就叫下品中生。佛告诉阿难和韦提希：下品下生的：或有众生作不善业、犯五逆十恶，具足种种不善；这样的愚人以恶业的缘故，应堕恶道，经历多劫受苦无穷。这愚人临命终时，遇到善知识种种安慰，为说妙法，教他念佛。那人被苦逼迫，来不及念佛。善友告诉他：你若不能念那佛，应当称“归命无量寿佛”。如此至心，令声音不断，具足十念称南无阿弥陀佛——称佛名的缘故，在念念之中除八十亿劫生死之罪。命终的时候，见金莲花犹如日轮住在那人面前，如一念顷即得往生极乐世界。在莲花中满十二大劫，莲花才开；当花开时，观世音、大势至以大悲音声为那人广说实相、除灭罪业之法；听了欢喜，当下即发菩提之心。这就叫下品下生。这叫做下辈生想，名叫第十六观。</p></div><div class="su-pair"><p class="su-org">尔时世尊说是语时。韦提希与五百侍女。闻佛所说。应时即见极乐世界广长之相。得见佛身及二菩萨。心生欢喜叹未曾有。豁然大悟得无生忍。五百侍女发阿耨多罗三藐三菩提心。愿生彼国。世尊悉记皆当往生。生彼国已。获得诸佛现前三昧。无量诸天发无上道心。</p><p class="su-tra">世尊说这话时，韦提希与五百侍女闻佛所说，当下即见极乐世界广长之相，得以见佛身和两位菩萨，心生欢喜，叹未曾有，豁然大悟，得无生法忍。五百侍女发无上正等正觉之心，愿生彼国；世尊为她们全部授记，都当往生。生彼国后，获得诸佛现前三昧。无量诸天也发了无上道心。</p></div><div class="su-pair"><p class="su-org">尔时阿难。即从座起前白佛言。世尊。当何名此经。此法之要当云何受持。佛告阿难。此经名观极乐国土无量寿佛观世音菩萨大势至菩萨。亦名净除业障生诸佛前。汝等受持无令忘失。行此三昧者。现身得见无量寿佛及二大士。若善男子及善女人。但闻佛名二菩萨名。除无量劫生死之罪。何况忆念。若念佛者。当知此人即是人中芬陀利花。观世音菩萨大势至菩萨。为其胜友。当坐道场生诸佛家。</p><p class="su-tra">这时阿难从座而起，上前白佛：世尊，这部经该叫什么名字？这法之要，我们应当怎样受持？佛告诉阿难：这部经名叫《观极乐国土无量寿佛观世音菩萨大势至菩萨》，也名叫《净除业障生诸佛前》。你们要受持，不要忘失。行这三昧的人，现身就能见无量寿佛和两位大士。若是善男子、善女人，只听佛名和两位菩萨名，即除无量劫生死之罪，何况忆念。若念佛的人，当知这人就是人中的芬陀利花（白莲花）；观世音菩萨、大势至菩萨做他的胜友，将来必坐道场、生于诸佛之家。</p></div><div class="su-pair"><p class="su-org">佛告阿难。汝好持是语。持是语者即是持无量寿佛名。佛说此语时。尊者目连。尊者阿难。及韦提希等。闻佛所说。皆大欢喜。</p><p class="su-tra">佛告诉阿难：你要好好受持这话；受持这话，就是受持无量寿佛的名号。佛说这话时，尊者目犍连、尊者阿难以及韦提希等，闻佛所说，都大欢喜。</p></div><div class="su-pair"><p class="su-org">尔时世尊。足步虚空还耆阇崛山。尔时阿难。广为大众说如上事。无量人天龙神夜叉。闻佛所说皆大欢喜礼佛而退</p><p class="su-tra">那时世尊举足腾空，回到耆阇崛山。阿难广为大众宣说上面的事。无量的人、天、龙、神、夜叉，闻佛所说，都大欢喜，礼佛而退。</p></div></div></div>',4)])])}const n=a(l,[["render",c]]);export{g as __pageData,n as default};
